/** Uppercase the first character. */
export function capitalize(s: string): string {
  return s.length ? s[0].toUpperCase() + s.slice(1) : s;
}

/** Cut to at most `max` characters, ending with "…" when cut. */
export function truncate(s: string, max: number): string {
  if (max < 1) throw new RangeError('max must be >= 1');
  return s.length <= max ? s : s.slice(0, max - 1) + '…';
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { capitalize, truncate } from '../src/text.ts';

test('capitalize', () => {
  assert.equal(capitalize('hello'), 'Hello');
  assert.equal(capitalize(''), '');
});

test('truncate', () => {
  assert.equal(truncate('hello', 10), 'hello');
  assert.equal(truncate('hello world', 6), 'hello…');
  assert.throws(() => truncate('x', 0), RangeError);
});
{
  "name": "textkit",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Tiny string helpers (TypeScript, no dependencies; Node 22.18+ runs .ts directly).",
  "scripts": {
    "test": "node --test \"test/**/*.test.ts\""
  }
}

